import{uid,localDate,monthOf,rupiah,empty,demo,validate,balance,monthly,spent,csv,amount}from'./core.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mode='demo',state,month=monthOf(localDate()),page='dashboard',filter={q:'',type:'',account:''},editing=null,hidden=false,loadError=false;
try{mode=localStorage.getItem('ruanguang-mode')==='personal'?'personal':'demo'}catch{}
const key=()=>`ruanguang-v1-${mode}`;
function read(){try{const raw=localStorage.getItem(key());state=raw?validate(JSON.parse(raw)):mode==='demo'?demo():empty();loadError=false}catch{state=empty();loadError=true;toast('Data tersimpan tidak bisa dibaca. Tidak ada data lama yang ditimpa. Pulihkan dari backup.')}}
function save(next){validate(next);try{if(loadError)throw Error('Pulihkan backup terlebih dahulu.');localStorage.setItem(key(),JSON.stringify(next));state=next;return true}catch(e){toast('Gagal menyimpan: '+e.message);return false}}
function mutate(fn){const next=structuredClone(state);fn(next);if(save(next)){render();return true}return false}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)}
const money=n=>hidden?'Rp ••••••':rupiah(n),cat=id=>state.categories.find(c=>c.id===id),acc=id=>state.accounts.find(a=>a.id===id),percent=(a,b)=>b?Math.min(100,Math.max(0,a/b*100)):0;
const nav=[['dashboard','◫','Ringkasan'],['transactions','⇄','Transaksi'],['accounts','▣','Rekening & dompet'],['budgets','◉','Anggaran'],['goals','⚑','Target tabungan'],['bills','▤','Tagihan rutin'],['reports','▥','Laporan'],['settings','⚙','Pengaturan']];
const action=(a,text,extra='',cls='')=>`<button class="${cls}" data-action="${a}" ${extra}>${text}</button>`;
const monthLabel=()=>new Date(month+'-15T12:00:00').toLocaleDateString('id-ID',{month:'long',year:'numeric'});
function title(eyebrow,heading,desc,button=''){return`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p>${desc}</p></div><div class="heading-actions"><label class="month-control"><span>▦</span><input type="month" id="month" aria-label="Bulan laporan" value="${month}" required></label>${button}</div></div>`}
function categoryRows(m,limit=99){return state.categories.filter(c=>c.type==='expense').map(c=>({...c,total:spent(state,m,c.id)})).filter(c=>c.total>0).sort((a,b)=>b.total-a.total).slice(0,limit)}
function table(ts){if(!ts.length)return`<div class="empty"><span>↗</span><h3>Belum ada transaksi</h3><p>Mulai dari pengeluaran kecil atau pemasukan pertamamu.</p>${action('transaction','+ Catat transaksi','','button secondary')}</div>`;return`<div class="table-scroll"><table><thead><tr><th>Transaksi</th><th>Tanggal</th><th>Rekening</th><th class="right">Jumlah</th><th><span class="sr">Aksi</span></th></tr></thead><tbody>${ts.map(t=>{const c=cat(t.category);return`<tr><td><div class="transaction-name"><span class="category-icon" style="background:${c?.color||'#adc2aa'}25;color:${c?.color||'#66875b'}">${esc(c?.icon||'⇄')}</span><div><strong>${esc(t.note||c?.name||'Transfer rekening')}</strong><small>${esc(c?.name||'Transfer internal')}</small></div></div></td><td>${new Date(t.date+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</td><td>${esc(acc(t.account)?.name)}${t.to?' → '+esc(acc(t.to)?.name):''}</td><td class="right ${t.type==='income'?'positive':t.type==='expense'?'negative':''}"><b>${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount)}</b></td><td><div class="row-actions">${action('transaction','✎',`data-id="${t.id}" aria-label="Edit transaksi ${esc(t.note)}"`)}${action('delete','×',`data-collection="transactions" data-id="${t.id}" aria-label="Hapus transaksi ${esc(t.note)}"`)}</div></td></tr>`}).join('')}</tbody></table></div>`}
function chart(){const maxDay=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const bins=Array.from({length:6},(_,i)=>({label:`${i*5+1}${i===5?'–'+maxDay:'–'+(i+1)*5}`,income:0,expense:0}));monthly(state,month).ts.forEach(t=>{if(t.type!=='transfer')bins[Math.min(5,Math.floor((Number(t.date.slice(-2))-1)/5))][t.type]+=t.amount});const max=Math.max(...bins.flatMap(b=>[b.income,b.expense]),1);return`<div class="chart" aria-label="Arus kas per kelompok lima hari">${bins.map(b=>`<div class="bar-group"><div class="bars"><div class="bar income" style="height:${Math.max(2,b.income/max*150)}px" title="Pemasukan: ${money(b.income)}"></div><div class="bar expense" style="height:${Math.max(2,b.expense/max*150)}px" title="Pengeluaran: ${money(b.expense)}"></div></div><span>${b.label}</span><small>${hidden?'•••':new Intl.NumberFormat('id-ID',{notation:'compact'}).format(b.income-b.expense)}</small></div>`).join('')}</div>`}
function budgetCard(b){const c=cat(b.category),n=spent(state,b.month,b.category),over=n>b.limit;return`<div class="budget-item"><div class="budget-top"><span><i style="background:${c.color}"></i>${esc(c.name)}</span><b class="${over?'negative':''}">${Math.round(n/b.limit*100)}%</b></div><div class="progress"><span style="width:${percent(n,b.limit)}%;background:${over?'#c77865':c.color}"></span></div><div class="budget-bottom"><span>${money(n)} <em>/ ${money(b.limit)}</em></span><small>${over?'Melebihi anggaran':money(b.limit-n)+' tersisa'}</small></div></div>`}
function dashboard(){const m=monthly(state,month),total=state.accounts.reduce((n,a)=>n+balance(state,a.id),0),bs=state.budgets.filter(b=>b.month===month);return title('GAMBARAN BESAR, LANGKAH KECIL',`Halo, ${esc(state.name)} <span class="wave">✦</span>`,'Mari beri ruang untuk keuangan yang lebih terencana.',action('transaction','+ Tambah transaksi','','button primary'))+`<div class="metrics"><article class="metric balance"><div>Total saldo ${action('visibility',hidden?'◉':'◎','aria-label="Tampilkan atau sembunyikan nominal"')}</div><h2>${money(total)}</h2><small>Seluruh rekening · termasuk saldo awal</small><div class="balance-art">◒</div></article><article class="metric"><div><span class="metric-icon green">↙</span>Pemasukan</div><h2>${money(m.income)}</h2><small>${m.ts.filter(t=>t.type==='income').length} transaksi · ${monthLabel()}</small></article><article class="metric"><div><span class="metric-icon orange">↗</span>Pengeluaran</div><h2>${money(m.expense)}</h2><small>${m.ts.filter(t=>t.type==='expense').length} transaksi · ${monthLabel()}</small></article><article class="metric"><div><span class="metric-icon purple">◇</span>Sisa arus kas</div><h2>${money(m.net)}</h2><small>${m.income?Math.round(m.net/m.income*100)+'% dari pemasukan':'Belum ada pemasukan'} · bulan ini</small></article></div><div class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2>Arus kas</h2><p>Lihat ke mana uangmu bergerak.</p></div><div class="legend"><span><i></i>Pemasukan</span><span><i></i>Pengeluaran</span></div></div>${chart()}<div class="chart-footer"><span>↗ Catatan kecil, gambaran yang lebih jelas.</span>${action('navigate','Lihat laporan →','data-page="reports"')}</div></article><article class="panel"><div class="panel-head"><div><h2>Anggaran bulan ini</h2><p>Tetap di jalur rencanamu.</p></div>${action('navigate','↗','data-page="budgets" aria-label="Lihat anggaran"')}</div>${bs.length?bs.slice(0,3).map(budgetCard).join(''):`<div class="empty compact"><p>Belum ada anggaran untuk bulan ini.</p>${action('budget','+ Buat anggaran','','button secondary')}</div>`}</article><article class="panel transactions-panel"><div class="panel-head"><div><h2>Transaksi terbaru</h2><p>Semua tercatat, tidak ada yang terlewat.</p></div>${action('navigate','Lihat semua →','data-page="transactions"')}</div>${table([...m.ts].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))}</article><article class="panel goal-summary"><div class="panel-head"><div><h2>Selangkah lebih dekat</h2><p>Untuk hal-hal yang berarti.</p></div><span>⚑</span></div>${state.goals[0]?`<div class="goal-illustration">✳<span>YOUR NEXT CHAPTER</span></div><h3>${esc(state.goals[0].name)}</h3><p class="goal-amount">${money(state.goals[0].saved)} <span>/ ${money(state.goals[0].target)}</span></p><div class="progress"><span style="width:${percent(state.goals[0].saved,state.goals[0].target)}%"></span></div><div class="goal-foot"><span>${Math.round(percent(state.goals[0].saved,state.goals[0].target))}% terkumpul</span>${action('navigate','Lihat target →','data-page="goals"')}</div>`:`<div class="empty compact"><p>Wujudkan rencana besarmu, satu target dulu.</p>${action('goal','+ Buat target','','button secondary')}</div>`}</article></div>`}
function transactions(){const ts=monthly(state,month).ts.filter(t=>(!filter.type||t.type===filter.type)&&(!filter.account||t.account===filter.account||t.to===filter.account)&&`${t.note} ${cat(t.category)?.name||''}`.toLowerCase().includes(filter.q.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return title('CATAT, PAHAMI, RENCANAKAN','Semua transaksi','Transfer antarrekening tidak dihitung sebagai pemasukan atau pengeluaran.',action('transaction','+ Tambah transaksi','','button primary'))+`<div class="panel"><div class="filters"><input id="search" aria-label="Cari transaksi" placeholder="Cari catatan atau kategori…" value="${esc(filter.q)}"><select id="type-filter" aria-label="Jenis transaksi">${options([['','Semua jenis'],['income','Pemasukan'],['expense','Pengeluaran'],['transfer','Transfer']],filter.type)}</select><select id="account-filter" aria-label="Filter rekening">${options([['','Semua rekening'],...state.accounts.map(a=>[a.id,a.name])],filter.account)}</select>${action('csv','↓ Ekspor CSV','','button secondary')}</div>${table(ts)}<div class="table-footer">${ts.length} transaksi ditampilkan · ${monthLabel()}</div></div>`}
function accounts(){return title('SEMUA DALAM SATU PANDANGAN','Rekening & dompet','Saldo rekening dihitung dari saldo awal dan seluruh transaksi.',action('account','+ Tambah rekening','','button primary'))+`<div class="cards">${state.accounts.map(a=>`<article class="panel account-card"><div class="panel-head"><span class="account-icon" style="background:${a.color}">▣</span>${action('account','✎',`data-id="${a.id}" aria-label="Edit rekening ${esc(a.name)}"`)}</div><p>${a.kind==='bank'?'REKENING BANK':a.kind==='cash'?'UANG TUNAI':'DOMPET DIGITAL'}</p><h2>${esc(a.name)}</h2><h3>${money(balance(state,a.id))}</h3><div class="account-footer"><span>Saldo awal ${money(a.opening)}</span>${action('delete','Hapus',`data-collection="accounts" data-id="${a.id}"`)}</div></article>`).join('')}</div><div class="notice">ⓘ Saldo total menggunakan seluruh tanggal transaksi. Saldo awal bukan pemasukan bulanan. Rekening yang dipakai transaksi atau tagihan tidak dapat dihapus.</div>`}
function budgets(){const bs=state.budgets.filter(b=>b.month===month);return title('BERI BATAS, BUKAN BATASAN','Anggaran bulanan','Tetapkan batas untuk kategori pengeluaran yang ingin kamu jaga.',action('budget','+ Buat anggaran','','button primary'))+`<div class="cards">${bs.length?bs.map(b=>`<article class="panel">${budgetCard(b)}<div class="card-actions">${action('budget','Edit',`data-id="${b.id}"`)}${action('delete','Hapus',`data-collection="budgets" data-id="${b.id}"`)}</div></article>`).join(''):'<div class="panel empty">Belum ada anggaran. Buat anggaran pertama untuk bulan ini.</div>'}</div>`}
function goals(){return title('RENCANA BESAR DIMULAI DI SINI','Target tabungan','Pantau alokasi tabunganmu. Target tidak mengubah saldo rekening.',action('goal','+ Buat target','','button primary'))+`<div class="cards">${state.goals.length?state.goals.map(g=>`<article class="panel"><div class="panel-head"><span class="account-icon">⚑</span>${action('goal','✎',`data-id="${g.id}" aria-label="Edit target"`)}</div><h2>${esc(g.name)}</h2><p class="muted">Target ${new Date(g.deadline+'T12:00:00').toLocaleDateString('id-ID')}</p><h3>${money(g.saved)} <small class="muted">/ ${money(g.target)}</small></h3><div class="progress"><span style="width:${percent(g.saved,g.target)}%"></span></div><div class="goal-foot"><b>${Math.round(percent(g.saved,g.target))}% tercapai</b><span>${money(g.target-g.saved)} lagi</span></div><div class="card-actions">${action('topup','+ Tambah alokasi',`data-id="${g.id}"`,'button secondary')}${action('delete','Hapus',`data-collection="goals" data-id="${g.id}"`)}</div></article>`).join(''):'<div class="panel empty">Belum ada target tabungan. Mulai dari dana darurat atau rencana pribadi.</div>'}</div><div class="notice">ⓘ Alokasi target hanya pencatatan rencana, bukan transfer bank. Hindari menghitung uang yang sama pada beberapa target.</div>`}
function bills(){return title('LEBIH TENANG SAAT JATUH TEMPO','Tagihan rutin','Pengingat bulanan di aplikasi. Bayar akan mencatat pengeluaran, bukan mengirim uang.',action('bill','+ Tambah tagihan','','button primary'))+`<div class="panel">${state.bills.length?state.bills.map(b=>{const paid=b.paid.includes(month),day=Math.min(b.day,new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate());return`<div class="bill-row"><div class="date-badge"><b>${day}</b><span>TIAP BULAN</span></div><div><h3>${esc(b.name)}</h3><p>${esc(acc(b.account)?.name)} · ${esc(cat(b.category)?.name)}</p></div><strong>${money(b.amount)}</strong><span class="pill ${paid?'paid':''}">${paid?'Tercatat lunas':'Belum dibayar'}</span><div class="row-actions">${paid?'':action('pay','Catat pembayaran',`data-id="${b.id}"`,'button secondary')}${action('bill','✎',`data-id="${b.id}" aria-label="Edit tagihan"`)}${action('delete','×',`data-collection="bills" data-id="${b.id}" aria-label="Hapus tagihan"`)}</div></div>`}).join(''):'<div class="empty">Tambahkan tagihan bulanan seperti internet, sewa, atau langganan.</div>'}</div><div class="notice">ⓘ Tidak ada debit otomatis atau notifikasi saat aplikasi ditutup. Status pembayaran berlaku untuk bulan yang dipilih.</div>`}
function reports(){const m=monthly(state,month),rows=categoryRows(month),max=Math.max(...rows.map(c=>c.total),1);return title('ANGKA YANG BERCERITA','Laporan keuangan','Ringkasan berdasarkan transaksi pada bulan yang dipilih.',action('csv','↓ Ekspor CSV','','button secondary'))+`<div class="metrics three"><article class="metric"><div>Pemasukan</div><h2>${money(m.income)}</h2></article><article class="metric"><div>Pengeluaran</div><h2>${money(m.expense)}</h2></article><article class="metric balance"><div>Sisa arus kas</div><h2>${money(m.net)}</h2></article></div><div class="two-cols"><article class="panel"><div class="panel-head"><h2>Pengeluaran per kategori</h2></div>${rows.length?rows.map(c=>`<div class="budget-item"><div class="budget-top"><span>${esc(c.icon)} ${esc(c.name)}</span><b>${money(c.total)}</b></div><div class="progress"><span style="background:${c.color};width:${c.total/max*100}%"></span></div><small class="muted">${Math.round(c.total/m.expense*100)}% dari pengeluaran</small></div>`).join(''):'<div class="empty">Belum ada pengeluaran di bulan ini.</div>'}</article><article class="panel"><div class="panel-head"><h2>Arus kas sepanjang bulan</h2></div>${chart()}<div class="report-insight"><h3>Catatan bulan ini</h3><p>${m.expense>m.income?'Pengeluaran lebih besar dari pemasukan bulan ini. Tinjau kategori terbesar untuk memahami selisihnya.':m.income?'Pemasukan melebihi atau sama dengan pengeluaran. Sisa arus kas dapat membantu rencana tabunganmu.':'Catat pemasukan dan pengeluaran untuk melihat gambaran keuanganmu.'}</p><p>${rows[0]?'Kategori pengeluaran terbesar: <b>'+esc(rows[0].name)+'</b>.':''}</p></div></article></div>`}
function settings(){return title('SESUAIKAN RUANGMU','Pengaturan & data','Data disimpan di browser ini. Backup rutin agar catatan tetap aman.')+`<div class="two-cols"><article class="panel"><h2>Profil pribadi</h2><p class="muted">Nama yang muncul di dashboard.</p><form id="profile-form" class="inline-form"><input name="name" aria-label="Nama panggilan" required maxlength="60" value="${esc(state.name)}"><button class="button primary">Simpan nama</button></form><hr><h2>Kategori transaksi</h2><p class="muted">Tambahkan kategori sesuai kebiasaanmu.</p><div class="category-list">${state.categories.map(c=>`<span>${esc(c.icon)} ${esc(c.name)} <small>${c.type==='income'?'masuk':'keluar'}</small></span>`).join('')}</div>${action('category','+ Tambah kategori','','button secondary')}</article><article class="panel"><h2>Backup & pemulihan</h2><p class="muted">Backup JSON menyimpan seluruh data: rekening, transaksi, anggaran, target, dan tagihan. Impor menggantikan data pada mode aktif.</p><div class="settings-actions">${action('backup','↓ Unduh backup JSON','','button primary')}${action('import','↑ Pulihkan dari backup','','button secondary')}${action('csv','↓ Ekspor transaksi bulan ini','','button secondary')}</div><div class="notice">Data bersifat lokal, tidak tersinkron antarperangkat, dan tidak terenkripsi di browser. Menghapus data browser dapat menghapus catatan. Simpan backup di tempat yang aman.</div><hr><h2>Mode ${mode==='demo'?'demo':'pribadi'}</h2><p class="muted">Mode demo dan pribadi memiliki penyimpanan terpisah.</p>${action('mode',mode==='demo'?'Beralih ke catatan pribadi':'Jelajahi mode demo','','button secondary')}${mode==='demo'?action('reset-demo','Reset data demo','','button secondary'):''}</article></div>`}
function render(){const label=nav.find(n=>n[0]===page)?.[2]||'Ringkasan';$('nav').innerHTML=nav.map(([id,icon,name])=>`<a href="#${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}><span>${icon}</span>${name}${id===page?'<i></i>':''}</a>`).join('');$('breadcrumb').innerHTML=`Ruang pribadi <span>/</span> ${label}`;$('profile-name').textContent=state.name;$('avatar').textContent=state.name.slice(0,1).toUpperCase();$('demo-banner').hidden=mode!=='demo';$('mode-button').textContent=mode==='demo'?'Mode demo':'Mode pribadi';$('page').innerHTML=({dashboard,transactions,accounts,budgets,goals,bills,reports,settings}[page]||dashboard)();$('month')?.addEventListener('change',e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;render()}});$('search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;filter.q=e.target.value;render();$('search').focus();$('search').setSelectionRange(pos,pos)});$('type-filter')?.addEventListener('change',e=>{filter.type=e.target.value;render()});$('account-filter')?.addEventListener('change',e=>{filter.account=e.target.value;render()});$('profile-form')?.addEventListener('submit',e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;if(mutate(s=>s.name=name))toast('Nama diperbarui.')})}
function options(items,value){return items.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}
function input(name,label,value='',type='text',extra=''){return`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`}
const select=(name,label,items,value)=>`<label>${label}<select name="${name}" required>${options(items,value)}</select></label>`;
const cashInput=(name,label,value='')=>input(name,label,value,'number','min="1" max="1000000000000" step="1" inputmode="numeric"');
function open(kind,id){editing={kind,id};$('form-error').textContent='';const tx=kind==='transaction',collection={account:'accounts',budget:'budgets',goal:'goals',bill:'bills'}[kind],x=(tx?state.transactions:state[collection]||[]).find(o=>o.id===id)||{};const today=localDate(),date=monthOf(today)===month?today:month+'-01';const as=state.accounts.map(a=>[a.id,a.name]);$('modal-title').textContent={transaction:id?'Edit transaksi':'Catat transaksi',account:id?'Edit rekening':'Tambah rekening',budget:id?'Edit anggaran':'Buat anggaran',goal:id?'Edit target':'Target tabungan baru',bill:id?'Edit tagihan':'Tagihan rutin baru',category:'Kategori baru',topup:'Tambah alokasi tabungan'}[kind];let fields='';if(tx){fields=select('type','Jenis transaksi',[['expense','Pengeluaran'],['income','Pemasukan'],['transfer','Transfer']],x.type||'expense')+cashInput('amount','Nominal (Rp)',x.amount)+input('date','Tanggal',x.date||date,'date')+select('account','Rekening sumber / penerima',as,x.account)+`<div id="dependent"></div>`+input('note','Catatan',x.note||'','text','maxlength="300"');}if(kind==='account')fields=input('name','Nama rekening',x.name||'','text','maxlength="100"')+select('kind','Jenis',[['bank','Bank'],['cash','Tunai'],['ewallet','Dompet digital']],x.kind)+input('opening','Saldo awal (Rp)',x.opening??0,'number','min="-1000000000000" max="1000000000000" step="1"')+select('color','Warna',[['#b7ce9b','Hijau sage'],['#c5b9e0','Lavender'],['#f0cca1','Peach'],['#a9c6dd','Biru']],x.color);
if(kind==='budget')fields=select('category','Kategori',state.categories.filter(c=>c.type==='expense').map(c=>[c.id,c.name]),x.category)+cashInput('limit','Batas pengeluaran (Rp)',x.limit)+input('month','Bulan',x.month||month,'month');
if(kind==='goal')fields=input('name','Nama target',x.name||'','text','maxlength="100"')+cashInput('target','Jumlah target (Rp)',x.target)+input('saved','Sudah dialokasikan (Rp)',x.saved??0,'number','min="0" max="1000000000000" step="1"')+input('deadline','Tanggal target',x.deadline||today,'date');
if(kind==='bill')fields=input('name','Nama tagihan',x.name||'','text','maxlength="100"')+cashInput('amount','Nominal (Rp)',x.amount)+input('day','Tanggal jatuh tempo bulanan',x.day||1,'number','min="1" max="31" step="1"')+select('account','Dibayar dari',as,x.account)+select('category','Kategori pengeluaran',state.categories.filter(c=>c.type==='expense').map(c=>[c.id,c.name]),x.category)+`<p class="form-help">Tanggal 29–31 mengikuti hari terakhir jika bulan lebih pendek.</p>`;
if(kind==='category')fields=input('name','Nama kategori','','text','maxlength="100"')+select('type','Jenis',[['expense','Pengeluaran'],['income','Pemasukan']],'expense');
if(kind==='topup'){const g=state.goals.find(g=>g.id===id);fields=`<p>${esc(g.name)} · sisa target ${money(g.target-g.saved)}</p>`+cashInput('amount','Tambahan alokasi (Rp)')+'<p class="form-help">Pencatatan alokasi saja. Saldo rekening tidak berubah.</p>'}
$('fields').innerHTML=fields;if(tx){const type=$('editor').elements.type,dep=()=>{$('dependent').innerHTML=type.value==='transfer'?select('to','Rekening tujuan',as.filter(([id])=>id!==$('editor').elements.account.value),x.to):select('category','Kategori',state.categories.filter(c=>c.type===type.value).map(c=>[c.id,c.name]),x.category)};type.addEventListener('change',dep);$('editor').elements.account.addEventListener('change',dep);dep();$('editor').elements.note.required=false} $('modal').showModal()}
$('editor').addEventListener('submit',e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target)),{kind,id}=editing;for(const k of ['amount','opening','limit','target','saved','day'])if(k in d)d[k]=Number(d[k]);for(const k of ['name','note'])if(k in d)d[k]=d[k].trim();if(kind==='budget'&&state.budgets.some(b=>b.id!==id&&b.category===d.category&&b.month===d.month))throw Error('Kategori ini sudah memiliki anggaran pada bulan tersebut. Edit anggaran yang ada.');if(kind==='goal'&&d.saved>d.target)throw Error('Alokasi tidak boleh melebihi target.');if(kind==='category'&&state.categories.some(c=>c.type===d.type&&c.name.toLowerCase()===d.name.toLowerCase()))throw Error('Kategori sudah ada.');if(kind==='topup'){const g=state.goals.find(g=>g.id===id);if(!amount(d.amount)||g.saved+d.amount>g.target)throw Error('Jumlah melebihi sisa target.');if(!mutate(s=>s.goals.find(g=>g.id===id).saved+=d.amount))return}else{const collection={transaction:'transactions',account:'accounts',budget:'budgets',goal:'goals',bill:'bills',category:'categories'}[kind];let row={...d,id:id||uid()};if(kind==='transaction'){row.note=d.note||'';const old=state.transactions.find(t=>t.id===id);if(old?.billId){if(d.type!=='expense'||monthOf(d.date)!==monthOf(old.date))throw Error('Untuk mengubah jenis atau bulan pembayaran tagihan, hapus transaksi ini lalu catat ulang dari Tagihan rutin.');row.billId=old.billId;}if(d.type==='transfer'){row.category='';if(!d.to||d.to===d.account)throw Error('Pilih rekening tujuan yang berbeda.')}else row.to=''}if(kind==='bill')row.paid=state.bills.find(b=>b.id===id)?.paid||[];if(kind==='category'){row.icon='◇';row.color='#83b4a3'}const next=structuredClone(state);const index=next[collection].findIndex(r=>r.id===id);if(index>=0)next[collection][index]=row;else next[collection].push(row);validate(next);if(!save(next))return;render()}$('modal').close();toast('Berhasil disimpan.')}catch(err){$('form-error').textContent=err.message}});
function download(name,body,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function remove(collection,id){if(collection==='accounts'&&(state.accounts.length===1||state.transactions.some(t=>t.account===id||t.to===id)||state.bills.some(b=>b.account===id))){toast('Rekening terakhir atau rekening yang digunakan tidak dapat dihapus.');return}if(!confirm('Hapus catatan ini? Penghapusan akan mengubah perhitungan terkait.'))return;if(mutate(s=>{if(collection==='transactions'){const t=s.transactions.find(t=>t.id===id);if(t.billId){const b=s.bills.find(b=>b.id===t.billId);if(b)b.paid=b.paid.filter(m=>m!==monthOf(t.date))}}if(collection==='bills')s.transactions.forEach(t=>{if(t.billId===id)delete t.billId});s[collection]=s[collection].filter(x=>x.id!==id)}))toast('Catatan dihapus.')}
function pay(id){const b=state.bills.find(b=>b.id===id);if(b.paid.includes(month))return;if(!confirm(`Catat pengeluaran ${rupiah(b.amount)} untuk ${b.name} pada ${monthLabel()}? Tidak ada uang yang dikirim.`))return;const day=Math.min(b.day,new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate());if(mutate(s=>{s.transactions.push({id:uid(),type:'expense',amount:b.amount,account:b.account,category:b.category,note:b.name,date:month+'-'+String(day).padStart(2,'0'),to:'',billId:b.id});s.bills.find(x=>x.id===id).paid.push(month)}))toast('Pembayaran tercatat sebagai pengeluaran.')}
function switchMode(){mode=mode==='demo'?'personal':'demo';try{localStorage.setItem('ruanguang-mode',mode)}catch{}read();filter={q:'',type:'',account:''};render();toast(mode==='personal'?'Catatan pribadi siap. Data demo tidak ikut dipindahkan.':'Mode demo aktif.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='navigate'){location.hash=b.dataset.page;return}if(['transaction','account','budget','goal','bill','category','topup'].includes(a))open(a,b.dataset.id);else if(a==='close')$('modal').close();else if(a==='mode')switchMode();else if(a==='visibility'){hidden=!hidden;render()}else if(a==='delete')remove(b.dataset.collection,b.dataset.id);else if(a==='pay')pay(b.dataset.id);else if(a==='backup')download(`ruanguang-${mode}-${localDate()}.json`,JSON.stringify(state,null,2),'application/json');else if(a==='csv')download(`ruanguang-${month}.csv`,csv(state,monthly(state,month).ts.filter(t=>page!=='transactions'||((!filter.type||t.type===filter.type)&&(!filter.account||t.account===filter.account||t.to===filter.account)&&`${t.note} ${cat(t.category)?.name||''}`.toLowerCase().includes(filter.q.toLowerCase())))),'text/csv;charset=utf-8');else if(a==='import')$('import-file').click();else if(a==='reset-demo'&&confirm('Kembalikan data demo ke contoh awal?')){if(save(demo())){render();toast('Data demo direset.')}}});
$('import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>10000000)throw Error('Ukuran backup maksimum 10 MB.');const next=validate(JSON.parse(await f.text()));if(!confirm(`Ganti seluruh data ${mode==='demo'?'demo':'pribadi'} dengan backup berisi ${next.transactions.length} transaksi? Unduh backup saat ini terlebih dahulu jika diperlukan.`))return;const wasError=loadError;loadError=false;if(save(next)){render();toast('Backup berhasil dipulihkan.')}else loadError=wasError}catch(err){toast('Impor ditolak: '+err.message)}});
$('mobile-menu').onclick=()=>{const isOpen=document.body.classList.toggle('nav-open');$('mobile-menu').setAttribute('aria-expanded',String(isOpen))};window.addEventListener('hashchange',()=>{const wanted=location.hash.slice(1);page=nav.some(n=>n[0]===wanted)?wanted:'dashboard';document.body.classList.remove('nav-open');$('mobile-menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0)});read();page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'dashboard';render();
